package com.medibook.controller;
import com.medibook.entity.*;import com.medibook.repository.*;import com.medibook.dto.AdminDtos.*;import com.medibook.dto.DoctorDtos.ProfileUpdate;import com.medibook.service.DoctorService;import com.medibook.service.AppointmentService;import jakarta.validation.Valid;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.util.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminController {
 private final UserRepository users;private final DoctorProfileRepository doctors;private final AppointmentRepository appointments;private final AuditLogRepository audits;private final SpecialtyRepository specialties;private final PasswordEncoder encoder;private final DoctorService doctorService;private final AppointmentService appointmentService;
 public AdminController(UserRepository u,DoctorProfileRepository d,AppointmentRepository a,AuditLogRepository l,SpecialtyRepository s,PasswordEncoder encoder,DoctorService doctorService,AppointmentService appointmentService){users=u;doctors=d;appointments=a;audits=l;specialties=s;this.encoder=encoder;this.doctorService=doctorService;this.appointmentService=appointmentService;}
 @GetMapping("/dashboard") public Map<String,Object> dashboard(){return Map.of("patients",users.countByRole(Role.PATIENT),"doctors",users.countByRole(Role.DOCTOR),"appointments",appointments.count(),"pendingAppointments",appointments.countByStatus(AppointmentStatus.PENDING));}
 @GetMapping("/doctors") public List<Map<String,Object>> doctors(){return doctors.findAll().stream().map(d->Map.<String,Object>of("id",d.getUserId(),"name",d.getUser().getFullName(),"email",d.getUser().getEmail(),"specialty",d.getSpecialty()==null?"General Practice":d.getSpecialty().getName(),"location",d.getLocation()==null?"":d.getLocation(),"verified",d.isVerified(),"active",d.getUser().isActive())).toList();}
 @PostMapping("/doctors") @Transactional public Map<String,Object> createDoctor(@AuthenticationPrincipal Long actor,@Valid @RequestBody CreateDoctor in){String email=in.email().toLowerCase().trim();if(users.findByEmail(email).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email is already registered");AppUser user=users.save(new AppUser(email,encoder.encode(in.password()),in.fullName().trim(),Role.DOCTOR));Specialty specialty=specialties.findByNameIgnoreCase(in.specialty()).orElseGet(()->specialties.save(new Specialty(in.specialty().trim())));DoctorProfile profile=doctors.save(new DoctorProfile(user,specialty,in.qualifications(),in.experienceYears(),in.fee(),in.location(),in.bio()));profile.setVerified(in.verified());audits.save(new AuditLog(actor,"DOCTOR_CREATED","doctor="+user.getId()));return Map.of("id",user.getId(),"name",user.getFullName(),"email",email,"verified",profile.isVerified());}
 @PutMapping("/doctors/{id}/profile") @Transactional public Object updateDoctor(@PathVariable long id,@AuthenticationPrincipal Long actor,@Valid @RequestBody ProfileUpdate in){Object result=doctorService.updateProfile(id,in);audits.save(new AuditLog(actor,"DOCTOR_PROFILE_UPDATED","doctor="+id));return result;}
 @PatchMapping("/doctors/{id}/verification") @Transactional public Map<String,Object> verification(@PathVariable long id,@RequestParam boolean verified,@AuthenticationPrincipal Long actor){DoctorProfile d=doctors.findById(id).orElseThrow();d.setVerified(verified);audits.save(new AuditLog(actor,"DOCTOR_VERIFICATION","doctor="+id+", verified="+verified));return Map.of("id",id,"verified",verified);}
 @PatchMapping("/users/{id}/active") @Transactional public Map<String,Object> active(@PathVariable long id,@RequestParam boolean active,@AuthenticationPrincipal Long actor){AppUser u=users.findById(id).orElseThrow();u.setActive(active);audits.save(new AuditLog(actor,"USER_ACTIVE_STATE","user="+id+", active="+active));return Map.of("id",id,"active",active);}
 @GetMapping("/users") public List<Map<String,Object>> userList(@RequestParam(required=false) Role role){return users.findAll().stream().filter(u->role==null||u.getRole()==role).map(u->Map.<String,Object>of("id",u.getId(),"email",u.getEmail(),"fullName",u.getFullName(),"role",u.getRole().name(),"active",u.isActive())).toList();}
 @PostMapping("/specialties") @Transactional public Map<String,Object> createSpecialty(@AuthenticationPrincipal Long actor,@Valid @RequestBody SpecialtyInput in){if(specialties.findByNameIgnoreCase(in.name().trim()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Specialty already exists");Specialty s=specialties.save(new Specialty(in.name().trim()));audits.save(new AuditLog(actor,"SPECIALTY_CREATED","specialty="+s.getId()));return Map.of("id",s.getId(),"name",s.getName());}
 @PatchMapping("/specialties/{id}") @Transactional public Map<String,Object> updateSpecialty(@PathVariable long id,@AuthenticationPrincipal Long actor,@Valid @RequestBody SpecialtyInput in){Specialty s=specialties.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Specialty not found"));s.setName(in.name().trim());audits.save(new AuditLog(actor,"SPECIALTY_UPDATED","specialty="+id));return Map.of("id",id,"name",s.getName());}
 @GetMapping("/appointments") public org.springframework.data.domain.Page<Appointment> allAppointments(org.springframework.data.domain.Pageable pageable){return appointments.findAll(pageable);}
 @PatchMapping("/appointments/{id}/cancel") @Transactional public Map<String,Object> cancelAppointment(@PathVariable long id,@AuthenticationPrincipal Long actor){Appointment a=appointmentService.adminCancel(id);audits.save(new AuditLog(actor,"APPOINTMENT_CANCELLED","appointment="+id));return Map.of("id",a.getId(),"status",a.getStatus().name());}
 @GetMapping("/reports/trends") public List<Map<String,Object>> trends(){return appointments.monthlyTrends();}
 @GetMapping("/audit") public org.springframework.data.domain.Page<AuditLog> audit(org.springframework.data.domain.Pageable pageable){return audits.findAll(pageable);}
}
